import json
import os
from typing import Any, Dict, List

from composio_openai import App, ComposioToolSet, Action
from openai import OpenAI

USER_ID = "zealt-user01"
SUMMARY_PATH = "/home/user/summary.txt"
MODEL = os.getenv("OPENAI_MODEL", "gpt-4.1-mini")


def _resolve_actions(toolset: ComposioToolSet) -> List[Action]:
    """
    Use SEARCH_TOOLS to discover Slack tools, then resolve the actions needed.
    """
    toolset.search_tools(apps=[App.SLACK], search_string="conversations")
    toolset.search_tools(apps=[App.SLACK], search_string="chat post message")

    desired_action_names = [
        "SLACK_CONVERSATIONS_LIST",
        "SLACK_CONVERSATIONS_HISTORY",
        "SLACK_CHAT_POST_MESSAGE",
    ]

    actions: List[Action] = []
    for action_name in desired_action_names:
        action = getattr(Action, action_name, None)
        if action is not None:
            actions.append(action)

    return actions


def _execute_agent(tools: List[Dict[str, Any]]) -> str:
    client = OpenAI()
    messages: List[Dict[str, Any]] = [
        {
            "role": "system",
            "content": (
                "You are an AI agent with Slack tools."
                "\nTasks:"
                "\n1) Find a Slack channel named 'general' or the closest match."
                "\n2) Fetch the last 5 messages from that channel."
                "\n3) Summarize the messages into a single paragraph."
                "\n4) Post the summary back to the same channel."
                "\nReturn ONLY the summary text in your final response."
            ),
        },
        {
            "role": "user",
            "content": "Summarize the last 5 Slack messages and post the summary.",
        },
    ]

    while True:
        response = client.chat.completions.create(
            model=MODEL,
            messages=messages,
            tools=tools,
            tool_choice="auto",
        )
        message = response.choices[0].message
        messages.append(message)

        if not message.tool_calls:
            return (message.content or "").strip()

        tool_outputs = []
        for tool_call in message.tool_calls:
            output = toolset.execute_tool(tool_call)
            tool_outputs.append(
                {
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": json.dumps(output),
                }
            )

        messages.extend(tool_outputs)


def main() -> None:
    api_key = os.getenv("COMPOSIO_API_KEY")
    if not api_key:

